:root {
  --bg: #f4f6f3;
  --card-bg: #ffffff;
  --text: #2c3e35;
  --text-muted: #5a6e62;
  --sage: #738b7d;
  --sage-dark: #556b5e;
  --cream: #faf9f5;
  --border: #d4ded7;
  --radius: 12px;
}

* { box-sizing: border-box; margin: 0; padding: 0; }
body {
  font-family: system-ui, -apple-system, sans-serif;
  background: var(--bg);
  color: var(--text);
  line-height: 1.5;
  padding: 1.5rem;
}

.container {
  max-width: 900px;
  margin: 0 auto;
}

header {
  margin-bottom: 2rem;
  text-align: center;
}

h1 {
  font-size: 2rem;
  color: var(--sage-dark);
  margin-bottom: 0.5rem;
}

p.subtitle {
  color: var(--text-muted);
}

.card {
  background: var(--card-bg);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1.5rem;
  margin-bottom: 1.5rem;
  box-shadow: 0 4px 12px rgba(115, 139, 125, 0.08);
}

h2 {
  font-size: 1.25rem;
  color: var(--sage-dark);
  margin-bottom: 1rem;
}

.grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 1rem;
  margin-bottom: 1rem;
}

.field {
  display: flex;
  flex-direction: column;
}

label {
  font-size: 0.875rem;
  font-weight: 600;
  margin-bottom: 0.375rem;
  color: var(--sage-dark);
}

input {
  padding: 0.75rem;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--cream);
  font-size: 1rem;
  color: var(--text);
}

input:focus {
  outline: 2px solid var(--sage);
  border-color: transparent;
}

.btn-row {
  display: flex;
  gap: 1rem;
  margin-top: 1rem;
}

button {
  background: var(--sage);
  color: white;
  border: none;
  padding: 0.75rem 1.5rem;
  border-radius: 8px;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.2s;
}

button:hover {
  background: var(--sage-dark);
}

button:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

.result-box {
  background: var(--cream);
  border: 1px dashed var(--sage);
  padding: 1rem;
  border-radius: 8px;
  margin-top: 1rem;
  text-align: center;
}

.result-val {
  font-size: 1.5rem;
  font-weight: bold;
  color: var(--sage-dark);
}

table {
  width: 100%;
  border-collapse: collapse;
  margin-top: 1rem;
}

th, td {
  padding: 0.75rem;
  text-align: left;
  border-bottom: 1px solid var(--border);
  font-size: 0.95rem;
}

th {
  font-weight: 600;
  color: var(--sage-dark);
  background: var(--cream);
}

.empty-state {
  color: var(--text-muted);
  text-align: center;
  padding: 2rem;
}

.notice {
  background: #fff3cd;
  color: #856404;
  padding: 0.75rem;
  border-radius: 8px;
  margin-bottom: 1rem;
  font-size: 0.875rem;
}

