(async function() {
  let state = await lf.ready;
  let lastScaledResult = null;

  const ingredientInput = document.getElementById('ingredient');
  const amountInput = document.getElementById('amount');
  const originalServingsInput = document.getElementById('originalServings');
  const targetServingsInput = document.getElementById('targetServings');
  const calcBtn = document.getElementById('calcBtn');
  const saveBtn = document.getElementById('saveBtn');
  const calcResult = document.getElementById('calcResult');
  const resultVal = document.getElementById('resultVal');
  const calcError = document.getElementById('calcError');
  const previewNotice = document.getElementById('previewNotice');
  const savedContainer = document.getElementById('savedContainer');

  if (state.preview) {
    previewNotice.textContent = "Preview only. Publish to save changes.";
    previewNotice.style.display = "block";
  }

  function render(currentState) {
    const records = currentState.records || [];
    if (records.length === 0) {
      savedContainer.innerHTML = '<div class="empty-state">No saved calculations yet.</div>';
      return;
    }

    let html = `<table><thead><tr><th>Ingredient</th><th>Amount</th><th>Orig. Serv.</th><th>Target Serv.</th><th>Scaled</th><th>Action</th></tr></thead><tbody>`;
    for (const r of records) {
      const v = r.values || {};
      html += `<tr>
        <td>${escapeHtml(v.ingredient || '')}</td>
        <td>${escapeHtml(String(v.amount || ''))}</td>
        <td>${escapeHtml(String(v.originalServings || ''))}</td>
        <td>${escapeHtml(String(v.targetServings || ''))}</td>
        <td><strong>${escapeHtml(String(v.scaledAmount || ''))}</strong></td>
        <td><button data-id="${r.id}" class="del-btn" style="padding:0.25rem 0.5rem;font-size:0.8rem;background:#d9534f;">Delete</button></td>
      </tr>`;
    }
    html += `</tbody></table>`;
    savedContainer.innerHTML = html;

    savedContainer.querySelectorAll('.del-btn').forEach(btn => {
      btn.addEventListener('click', async () => {
        const id = btn.getAttribute('data-id');
        try {
          state = await lf.remove(id);
          render(state);
        } catch (err) {
          alert("Failed to delete: " + (err.message || err));
        }
      });
    });
  }

  function escapeHtml(str) {
    return str.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
  }

  calcBtn.addEventListener('click', async () => {
    calcError.style.display = 'none';
    calcResult.style.display = 'none';
    saveBtn.disabled = true;

    const amount = parseFloat(amountInput.value);
    const originalServings = parseFloat(originalServingsInput.value);
    const targetServings = parseFloat(targetServingsInput.value);

    if (isNaN(amount) || isNaN(originalServings) || isNaN(targetServings)) {
      calcError.textContent = "Please enter valid numeric values for amount and servings.";
      calcError.style.display = 'block';
      return;
    }

    if (!state.permissions.canUseTools && state.preview) {
      calcError.textContent = "Preview only: Publish to run tool.";
      calcError.style.display = 'block';
      return;
    }

    try {
      calcBtn.disabled = true;
      calcBtn.textContent = "Calculating...";
      const res = await lf.runTool("scale_recipe", 1, {
        amount,
        originalServings,
        targetServings
      });
      lastScaledResult = res.result.scaledAmount;
      resultVal.textContent = lastScaledResult;
      calcResult.style.display = 'block';
      saveBtn.disabled = false;
    } catch (err) {
      calcError.textContent = "Calculation failed: " + (err.message || err);
      calcError.style.display = 'block';
    } finally {
      calcBtn.disabled = false;
      calcBtn.textContent = "Calculate Scale";
    }
  });

  saveBtn.addEventListener('click', async () => {
    if (state.preview) {
      alert("Preview only. Publish to save changes.");
      return;
    }
    try {
      state = await lf.create({
        ingredient: ingredientInput.value || "Untitled",
        amount: parseFloat(amountInput.value),
        originalServings: parseFloat(originalServingsInput.value),
        targetServings: parseFloat(targetServingsInput.value),
        scaledAmount: lastScaledResult
      });
      render(state);
      saveBtn.disabled = true;
    } catch (err) {
      alert("Failed to save: " + (err.message || err));
    }
  });

  render(state);
  lf.subscribe(next => {
    state = next;
    render(state);
  });

  await lf.reportReady();
})();

